// Validar y normalizar la pregunta recibida del backend
const body = $json.body || $json;
const question = body.question || body.text || '';

if (!question || question.trim() === '') {
  return [{
    json: {
      error: true,
      message: 'La pregunta no puede estar vacía.',
      question: ''
    }
  }];
}

return [{
  json: {
    question: question.trim(),
    history: body.history || [],
    timestamp: new Date().toISOString()
  }
}];

// Formatear respuesta para el backend y frontend de React
const agentOutput = $json.output || $json.text || '';

return [{
  json: {
    answer: agentOutput,
    source: 'n8n Agente IA (Gemini 1.5 Flash + PostgreSQL)',
    timestamp: new Date().toISOString()
  }
}];
